const MILLISECONDS_IN_DAY = 24 * 60 * 60 * 1000

const dateFormatterCache = new Map()
const relativeTimeFormatter = new Intl.RelativeTimeFormat("en", { numeric: "auto" })

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_IN_DAY)
}

export function beginningOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

export function formatTimestamp(date, format = "date", now = new Date()) {
  switch (format) {
    case "time":
      return formatTime(date)
    case "date-time":
    case "datetime":
      return formatDateTime(date)
    case "full-date":
      return formatDate(date, { includeYear: true })
    case "comment":
      return formatCommentDate(date, now)
    case "relative":
      return formatRelativeTime(date, now)
    case "future":
      return formatFutureDate(date, now)
    case "date":
    default:
      return formatDate(date, { now })
  }
}

export function formatTime(date) {
  return formatter({ hour: "numeric", minute: "2-digit" }).format(date)
}

export function formatDateTime(date) {
  return formatter({
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit"
  }).format(date)
}

export function formatDate(date, { includeYear = false, now = new Date() } = {}) {
  const options = { month: "short", day: "numeric" }

  if (includeYear || date.getFullYear() !== now.getFullYear()) {
    options.year = "numeric"
  }

  return formatter(options).format(date)
}

export function formatCommentDate(date, now = new Date()) {
  const daysAgo = signedDifferenceInDays(date, now)

  if (daysAgo < 0) {
    return formatFutureDate(date, now)
  } else if (daysAgo === 0) {
    return formatTime(date)
  } else if (daysAgo === 1) {
    return "yesterday"
  } else if (daysAgo < 7) {
    return `${daysAgo} days ago`
  } else {
    return formatDate(date, { now })
  }
}

export function formatFutureDate(date, now = new Date()) {
  const daysUntil = signedDifferenceInDays(now, date)

  if (daysUntil < 0) {
    return formatRelativeTime(date, now)
  } else if (daysUntil === 0) {
    return formatRelativeTime(date, now)
  } else if (daysUntil === 1) {
    return "tomorrow"
  } else {
    return `in ${daysUntil} days`
  }
}

export function formatRelativeTime(date, now = new Date()) {
  const differenceInSeconds = (date - now) / 1000
  const absoluteDifferenceInSeconds = Math.abs(differenceInSeconds)
  let unit
  let divisor

  if (absoluteDifferenceInSeconds < 60) {
    unit = "second"
    divisor = 1
  } else if (absoluteDifferenceInSeconds < 60 * 60) {
    unit = "minute"
    divisor = 60
  } else if (absoluteDifferenceInSeconds < 24 * 60 * 60) {
    unit = "hour"
    divisor = 60 * 60
  } else if (absoluteDifferenceInSeconds < 7 * 24 * 60 * 60) {
    unit = "day"
    divisor = 24 * 60 * 60
  } else if (absoluteDifferenceInSeconds < 30 * 24 * 60 * 60) {
    unit = "week"
    divisor = 7 * 24 * 60 * 60
  } else if (absoluteDifferenceInSeconds < 365 * 24 * 60 * 60) {
    unit = "month"
    divisor = 30 * 24 * 60 * 60
  } else {
    unit = "year"
    divisor = 365 * 24 * 60 * 60
  }

  return relativeTimeFormatter.format(Math.round(differenceInSeconds / divisor), unit)
}

function formatter(options) {
  const key = JSON.stringify(options)

  if (!dateFormatterCache.has(key)) {
    dateFormatterCache.set(key, new Intl.DateTimeFormat("en-US", options))
  }

  return dateFormatterCache.get(key)
}
